mapper.update:
UPDATE meeting_confirmation SET status = #{toStatus}, confirm_comment = #{comment},
  last_event_id = #{eventId}, revision = revision + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND binding_id = #{bindingId} AND business_key = #{businessKey}
  AND status = 'pending' AND task_version = #{expectedVersion}
  AND (last_event_id IS NULL OR last_event_id <> #{eventId})

UPDATE meeting_confirmation SET card_message_id = #{messageId}, card_command_id = #{commandId},
  updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND binding_id = #{bindingId} AND business_key = #{businessKey}

UPDATE meeting_confirmation SET card_claim_token = #{token}, card_lease_until = #{leaseUntil},
  card_status = 'sending', card_attempt_count = card_attempt_count + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND status = 'pending'
  AND card_status IN ('pending','failed') AND card_attempt_count < card_max_attempts
  AND card_next_attempt_at <= #{now}
  AND (card_claim_token IS NULL OR card_lease_until <= #{now})

UPDATE meeting_confirmation SET card_status = 'sent', card_message_id = #{messageId},
  card_claim_token = NULL, card_lease_until = NULL, card_last_error = NULL,
  revision = revision + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND card_claim_token = #{token}

UPDATE meeting_confirmation SET card_status = #{status}, card_next_attempt_at = #{nextAttemptAt},
  card_claim_token = NULL, card_lease_until = NULL, card_last_error = #{error},
  updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND card_claim_token = #{token}

UPDATE meeting_confirmation SET card_status = 'unknown', card_claim_token = NULL, card_lease_until = NULL,
  card_last_error = #{error}, revision = revision + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND card_claim_token = #{token}
